24	// The audit identifies the project and the label by `project=<project>` / `tag=<tag>`; the change
25	// request does not fix whether that is the row's id or its name, so each is matched against EITHER its
26	// seeded id OR its seeded name (ids and names are chosen so neither is a substring of the other). The
27	// record is still pinned exactly otherwise — the verb, the two field names, and that exactly one line
28	// is appended per action — so this stays a strong assertion, not a loose one.
29	//
30	// This SHOULD FAIL before the change: today a project's detail page has no tags region, no add form,
31	// and nothing is recorded when a project is labelled or unlabelled.
32	import { test, expect } from '@playwright/test';
33	import { resetAndSeed } from '../support/seed';
34	import { auditLines } from '../support/audit';
