49	        { id: 3, name: 'Backend' },
50	      ],
51	      projectTags: [
52	        { projectId: 1, tagId: 1 }, // Frontend -> project 1
53	        { projectId: 1, tagId: 2 }, // Urgent   -> project 1
54	        { projectId: 2, tagId: 2 }, // Urgent   -> project 2 (shared)
55	        { projectId: 2, tagId: 3 }, // Backend  -> project 2
56	      ],
57	    });
58	
59	    // Project 1: its two labels show in the tags list; the other project's exclusive label does not.
60	    await page.goto('/projects');
61	    await page.getByTestId('project-open-1').click();
62	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
63	
64	    const tags1 = page.getByTestId('project-tags');
65	    await expect(tags1).toBeVisible();
