1	// Acceptance tests for the change request:
2	//   "Let me see just the open tasks on a project. Or just the finished ones."
3	//
4	// A project's detail page already lists all of that project's tasks (project-tasks-table), each row
5	// (task-row-<id>) carrying a status (task-status) that reads one way while the task is open and a
6	// different way once it is finished/done. This change adds a control (task-filter) on the project
7	// detail page that narrows that list to ONE state: pick "open" and only the not-done tasks remain;
8	// pick "finished" and only the done tasks remain. With nothing picked (the default) every task is
9	// still shown, exactly as before, so this is a pure narrowing on top of the existing checklist.
10	//
11	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the filter is driven
12	// through the task-filter control. Seed honours clients: { id, name, email },
13	// projects: { id, clientId, name } and tasks: { id, projectId, title, done }.
14	//
15	// The filter is a single control (one testid), so it is a <select> of the states — mirroring the
16	// sibling invoice-status-filter. We do not assume the casing or exact wording of its option labels or
17	// values: for a wanted state we locate the option whose visible text OR value matches the state
18	// (open vs finished/done) case-insensitively and select it by its own value, and to clear we select
19	// the "all" option (value === '' or an "all" label). So a correct implementation passes whether it
20	// renders the finished state as 'DONE'/'Done'/'Finished' and whatever value it carries.
21	//
22	// The status LABEL text is not hard-coded (the request does not fix any wording): the test reads the
23	// open status and the finished status off reference rows while all are shown, then asserts that each
24	// surviving row carries the matching status after a narrow. This SHOULD FAIL before the change: there
25	// is no task-filter on the project detail page today.
26	import { test, expect, type Page } from '@playwright/test';
27	import { resetAndSeed } from '../support/seed';
28	
29	// A single project's checklist with a mix: two OPEN tasks (1, 2) and two FINISHED tasks (3, 4). A
30	// genuine "narrow to open" keeps 1 and 2 while hiding 3 and 4, and "narrow to finished" does the
31	// reverse — so neither narrow can be faked by always keeping one hard-coded row. A second project
32	// with its own task exists so the per-project scoping that already holds is not disturbed.
33	const FIXTURE = {
34	  clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
35	  projects: [
36	    { id: 1, clientId: 1, name: 'Website redesign' },
37	    { id: 2, clientId: 1, name: 'Warehouse automation' },
38	  ],
39	  tasks: [
40	    { id: 1, projectId: 1, title: 'Design the homepage', done: false },
41	    { id: 2, projectId: 1, title: 'Write the copy', done: false },
42	    { id: 3, projectId: 1, title: 'Register the domain', done: true },
43	    { id: 4, projectId: 1, title: 'Sign off the brief', done: true },
44	    // Belongs to another project — never shown on project 1's page, filter or no filter.
45	    { id: 5, projectId: 2, title: 'Install the conveyor', done: false },
46	  ],
47	};
48	
49	// The <option> value whose visible text OR value matches `state` (case-insensitive). Selecting by the
50	// option's own value keeps us agnostic to the label/value casing the feature chose.
51	async function optionValueFor(page: Page, state: RegExp): Promise<string> {
52	  const value = await page
53	    .getByTestId('task-filter')
54	    .locator('option')
55	    .evaluateAll((opts, src) => {
56	      const re = new RegExp(src as string, 'i');
57	      const match = (opts as HTMLOptionElement[]).find(
58	        (o) => re.test((o.textContent ?? '').trim()) || re.test(o.value),
59	      );
60	      return match ? match.value : null;
61	    }, state.source);
62	  if (value === null) {
63	    throw new Error(`task-filter has no option matching ${state}`);
64	  }
65	  return value;
66	}
67	
68	// Narrow the list to a single state through the control. "open" tasks are the not-done ones;
69	// "finished" tasks read as done (DONE / Done / Finished / Complete — matched loosely).
70	async function narrowTo(page: Page, state: RegExp): Promise<void> {
71	  await page.getByTestId('task-filter').selectOption(await optionValueFor(page, state));
72	}
73	
74	// The "show every task" option: an empty value by convention, or an option labelled "all".
75	async function showAll(page: Page): Promise<void> {
76	  const value = await page
77	    .getByTestId('task-filter')
78	    .locator('option')
79	    .evaluateAll((opts) => {
80	      const match = (opts as HTMLOptionElement[]).find(
81	        (o) => o.value === '' || /all/i.test((o.textContent ?? '').trim()),
82	      );
83	      return match ? match.value : null;
84	    });
85	  if (value === null) {
86	    throw new Error('task-filter has no "all" option');
87	  }
88	  await page.getByTestId('task-filter').selectOption(value);
89	}
90	
91	const OPEN = /open/i;
92	const FINISHED = /finish|done|complete/i;
93	
94	// Read the status wording the app uses for an open row and a finished row, off reference rows while
95	// every task is still shown. Done and open must look different, else "status" conveys nothing.
96	async function referenceStatuses(page: Page): Promise<{ open: string; finished: string }> {
97	  const open = ((await page.getByTestId('task-row-1').getByTestId('task-status').textContent()) ?? '').trim();
98	  const finished = ((await page.getByTestId('task-row-3').getByTestId('task-status').textContent()) ?? '').trim();
99	  expect(finished).not.toBe(open);
100	  return { open, finished };
101	}
102	
103	test.describe('narrow a project task list to open or finished', () => {
104	  test.beforeEach(async ({ page }) => {
105	    await resetAndSeed(FIXTURE);
106	    await page.goto('/projects');
107	    await page.getByTestId('project-open-1').click();
108	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
109	    await expect(page.getByTestId('project-tasks-table')).toBeVisible();
110	  });
111	
112	  test('with nothing picked, the filter is present and every task is shown', async ({ page }) => {
113	    await expect(page.getByTestId('task-filter')).toBeVisible();
114	
115	    // Default view: all four of project 1's tasks, open and finished alike.
116	    await expect(page.getByTestId('task-row-1')).toBeVisible();
