33	// ['projects'] so every view of projects re-reads from the server and the row drops — the list is
34	// never hand-edited after the write (CLAUDE.md rule 5). The audit record is written server-side.
35	export function useDeleteProject() {
36	  const queryClient = useQueryClient();
37	  return useMutation({
38	    mutationFn: (id: number) => postJson<{ id: number }>('/api/projects/remove', { id }),
39	    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
40	  });
41	}
42	
43	// Archive a project instead of deleting it: POSTs {id} and returns the id archived. The project is
44	// kept server-side with its archived flag set; invalidating ['projects'] re-reads every view so the
45	// row drops off the lists with no hand-maintained list (CLAUDE.md rule 5). The audit record is
46	// written server-side.
47	export function useArchiveProject() {
48	  const queryClient = useQueryClient();
49	  return useMutation({
50	    mutationFn: (id: number) => postJson<{ id: number }>('/api/projects/archive', { id }),
51	    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
52	  });
53	}
