56	// clients feature; the two stay in step through the key, not a dependency.
57	type ClientOption = { id: number; name: string };
58	
59	export function useClientOptions() {
60	  return useQuery({
61	    queryKey: ['clients'] as const,
62	    queryFn: () => getJson<ClientOption[]>('/api/clients'),
